<script setup>
import OAIReturnReply from './OAIReturnReply.vue'
import ProOAICaseFlow from './ProOAICaseFlow.vue'
import {caseOAIConfirmed} from '../oai-confirmation'
import { returnStates } from '../nexovcc'
import { formatTime } from '../utils'
import NexovccCaseAmounts from './NexovccCaseAmounts.vue'
import NexovccReturnNotice from './NexovccReturnNotice.vue'
import { caseReturnNotice } from '../nexovcc-return-notice'
defineProps({rows:{type:Array,default:()=>[]},finance:{type:Object,default:()=>({})},cards:{type:Array,default:()=>[]},data:{type:Object,default:()=>({})},running:Boolean,compact:Boolean})
defineEmits(['state','match','details','card','updated'])
const at=v=>v&&!v.startsWith('0001')&&Number.isFinite(Date.parse(v))?formatTime(v):'—'
const provider=v=>({xupay:'序付',cmsnav:'CMSNAV',tokenseek:'TokenSeek',gptpay:'GPTPay'}[v]||v||'—')
const returnedAt=row=>row.match?.group?.returned_at&&!row.match.group.returned_at.startsWith('0001')?row.match.group.returned_at:''
</script>
<template>
 <div v-if="compact" class="return-summaries"><article v-for="row in rows" :key="row.id" class="return-summary"><header><div><strong>{{row.email}}</strong><small v-if="row.pro_dead" class="warning" :title="row.pro_dead.reason">死号 · 关联卡片已禁用</small><small>订单 {{row.id}}{{row.deleted?' · 账号已删除':''}}</small></div><div class="summary-status"><div><OAIReturnReply :rows="[row]"><span class="case-status"><span class="case-badge" :class="row.state">{{returnStates[row.state]||'待核实'}}</span><small v-if="row.state==='waiting'&&caseOAIConfirmed(row)" class="oai-return-highlight">✓ OAI 已确认</small></span></OAIReturnReply><NexovccReturnNotice :notice="caseReturnNotice(data,row)"/></div><button :disabled="running" @click="$emit('state',row)">调整状态</button></div></header><ProOAICaseFlow :row="row" @updated="$emit('updated')"/><div class="summary-meta"><button :disabled="!cards.some(c=>c.card.id===row.card_id)" @click="$emit('card',row)">{{row.card_name||'环球卡片'}} · {{row.last4||'—'}}</button><span>{{provider(row.provider)}} / {{row.plan||'—'}}</span><span>开通 {{at(row.opened_at)}}</span><span>申请 {{at(row.requested_at)}}</span><span>回款 {{at(returnedAt(row))}}</span><span v-if="row.manual_state" :title="row.reason">人工设置 {{at(row.updated_at)}}</span></div><NexovccCaseAmounts :row="row" :finance="finance" :running="running" @details="$emit('details',$event)" @match="$emit('match',$event)"/></article><p v-if="!rows.length" class="empty">暂无符合条件的账号</p></div>
 <div v-else class="case-table"><table><thead><tr><th>账号 / 开通订单</th><th>银行卡 / 套餐</th><th>状态</th><th>OAI 确认</th><th>开通 / 申请时间</th><th>付款 / 回款 / 差额 / 消费收益</th></tr></thead>
 <tbody><tr v-for="row in rows" :key="row.id"><td class="account-cell"><strong>{{row.email}}</strong><small v-if="row.pro_dead" class="warning" :title="row.pro_dead.reason">死号 · 关联卡片已禁用</small><small>{{row.id}}</small><small v-if="row.deleted" class="warning">账号已删除 · 记录保留</small><small v-if="row.payment_status!=='success'">{{row.payment_status==='failed'?'开通失败':'开通结果待确认'}}</small></td>
 <td class="card-cell"><button :disabled="!cards.some(c=>c.card.id===row.card_id)" @click="$emit('card',row)">{{row.card_name||'环球卡片'}} · {{row.last4||'—'}}</button><small>{{provider(row.provider)}} / {{row.plan||'—'}}</small></td>
 <td class="state-cell"><OAIReturnReply :rows="[row]"><span class="case-status"><span class="case-badge" :class="row.state">{{returnStates[row.state]||'待核实'}}<small v-if="row.state==='waiting'">申请 {{at(row.requested_at)}}</small></span><small v-if="row.state==='waiting'&&caseOAIConfirmed(row)" class="oai-return-highlight">✓ OAI 已确认</small></span></OAIReturnReply><NexovccReturnNotice :notice="caseReturnNotice(data,row)"/><small v-if="row.manual_state" :title="row.reason">人工设置</small><small v-if="row.manual_state">设置于 {{at(row.updated_at)}}</small><button :disabled="running" :aria-label="'调整 '+row.email+' 的回款状态'" @click="$emit('state',row)">调整状态</button></td>
 <td><ProOAICaseFlow :row="row" @updated="$emit('updated')"/></td><td class="time-cell"><span>开通 {{at(row.opened_at)}}</span><small>申请 {{at(row.requested_at)}}</small><small v-if="returnedAt(row)">回款 {{at(returnedAt(row))}}</small><small>建单 {{at(row.created_at)}}</small></td>
 <td><NexovccCaseAmounts :row="row" :finance="finance" :running="running" @details="$emit('details',$event)" @match="$emit('match',$event)"/></td></tr>
 <tr v-if="!rows.length"><td colspan="6" class="empty">暂无符合条件的账号</td></tr></tbody></table></div>
 <p class="hint">付款与回款按同卡授权流水匹配，销卡退余额不计入账号回款；手动调整状态不会改变真实金额。</p>
</template>
