.return-summary{padding:20px 0;border-top:1px solid var(--line)}.return-summary header{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}.return-summary header strong{font-size:14px;overflow-wrap:anywhere}.summary-status{display:flex;align-items:center;gap:14px}.summary-meta{display:flex;flex-wrap:wrap;gap:8px 22px;margin:14px 0 20px;color:var(--muted);font-size:11px}.return-summary :deep(.account-money){min-width:0;max-width:none}.return-summary :deep(.fee-grid){column-gap:36px}.return-summary :deep(.amount-grid){padding:16px;background:var(--bg);border-radius:8px}@media(max-width:650px){.return-summary :deep(.amount-grid){grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.return-summary :deep(.fee-grid),.return-summary :deep(.result-row){grid-template-columns:1fr}.return-summary :deep(.result-row){gap:12px}}

.case-table{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:12px}th,td{padding:18px 16px;border-bottom:1px solid var(--line);vertical-align:top}th{background:var(--bg);color:var(--muted);font-weight:400;white-space:nowrap}.account-cell{min-width:190px;max-width:260px;overflow-wrap:anywhere}.account-cell strong{font-size:12px;font-weight:600}.card-cell{min-width:140px;max-width:190px;overflow-wrap:anywhere}.state-cell{min-width:130px}.time-cell{min-width:145px;font-size:11px;white-space:nowrap}small{display:block;font-size:10px;color:var(--muted);margin-top:7px;line-height:1.7}.case-badge{display:inline-block;padding:6px 8px;border-radius:5px;background:var(--bg);white-space:nowrap;font-size:11px}.case-badge small{font-size:9px;color:inherit;margin-top:3px}.returned{background:var(--green-soft);color:var(--green-strong)}.waiting{background:#fff6e4;color:#91651d}.opened{background:#eaf2ff;color:#376ec2}.warning{color:#a47523}.state-cell>button{display:block;margin-top:10px}button{background:none;border:0;color:var(--green-strong);font-size:11px;cursor:pointer;padding:0;text-align:left}button:disabled{opacity:.5;cursor:default}button:not(:disabled):hover{text-decoration:underline}.hint{font-size:11px;line-height:1.8;padding:0 16px;color:var(--muted)}.empty{text-align:center;padding:32px;color:var(--muted)}
</style>
